-- ---------------------------------------------------------------
-- lit:generos:1 · Narrativo, lírico e dramático
-- ---------------------------------------------------------------
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:1', 0, 'mc', $q$Um texto em versos em que um eu lírico expressa sentimentos e emoções pertence ao gênero:$q$, $j${"opts":["Dramático","Lírico","Narrativo","Jornalístico"],"a":1}$j$, $q$O gênero lírico é o da poesia que expressa emoções e a visão subjetiva de um eu lírico.$q$, 1);
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:1', 1, 'mc', $q$Uma peça escrita para ser encenada, com falas das personagens e rubricas, é um exemplo do gênero:$q$, $j${"opts":["Narrativo","Lírico","Dramático","Épico"],"a":2}$j$, $q$O gênero dramático é o do teatro: a história acontece pelas falas e ações das personagens, sem narrador.$q$, 1);
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:1', 2, 'mc', $q$Qual das obras abaixo é um romance, isto é, uma narrativa longa em prosa?$q$, $j${"opts":["Dom Casmurro, de Machado de Assis","Auto da Compadecida, de Ariano Suassuna","Canção do Exílio, de Gonçalves Dias","Os Lusíadas, de Camões"],"a":0}$j$, $q$Dom Casmurro é romance. O Auto da Compadecida é teatro, a Canção do Exílio é poema lírico e Os Lusíadas é uma epopeia em versos.$q$, 2);
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:1', 3, 'tf', $q$Julgue a afirmação sobre os gêneros literários$q$, $j${"stmt":"A divisão em gêneros épico (narrativo), lírico e dramático vem da Antiguidade grega e foi sistematizada por Aristóteles na Poética.","a":true}$j$, $q$Verdadeiro: a classificação clássica dos gêneros vem da Grécia antiga e da Poética de Aristóteles.$q$, 2);
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:1', 4, 'bank', $q$Complete a frase sobre os gêneros$q$, $j${"parts":["No gênero "," há um narrador que conta uma história; no gênero "," não há narrador: a história acontece pelas falas das personagens."],"a":["narrativo","dramático"],"extra":["lírico","jornalístico"]}$j$, $q$Narrativo tem narrador; dramático (teatro) tem só as falas e as rubricas.$q$, 1);
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:1', 5, 'match', $q$Associe o gênero ao exemplo$q$, $j${"pairs":[["Lírico","Soneto"],["Dramático","Comédia"],["Narrativo","Conto"],["Épico","Epopeia"]]}$j$, $q$Soneto é poema lírico; comédia é teatro; conto é narrativa curta; epopeia é o poema épico, narrativo em versos.$q$, 1);

-- lit:generos:2 · Elementos da narrativa
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:2', 0, 'mc', $q$O narrador que participa da história e conta os fatos em 1ª pessoa, como Bentinho em Dom Casmurro, é chamado de:$q$, $j${"opts":["Narrador observador","Narrador onisciente","Narrador-personagem","Narrador neutro"],"a":2}$j$, $q$Narrador-personagem: conta em 1ª pessoa e participa dos fatos, por isso sua visão é parcial.$q$, 1);
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:2', 1, 'mc', $q$O narrador que conhece os pensamentos e sentimentos de todas as personagens, sem participar da história, é o:$q$, $j${"opts":["Narrador-personagem","Narrador onisciente","Narrador-testemunha","Narrador protagonista"],"a":1}$j$, $q$Onisciente quer dizer que sabe tudo: entra na cabeça de qualquer personagem e narra em 3ª pessoa.$q$, 1);
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:2', 2, 'mc', $q$A personagem que se opõe ao protagonista e cria obstáculos para ele é chamada de:$q$, $j${"opts":["Antagonista","Coadjuvante","Figurante","Narrador"],"a":0}$j$, $q$Antagonista é quem se opõe ao protagonista; coadjuvantes ajudam e figurantes só compõem o cenário.$q$, 1);
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:2', 3, 'tf', $q$Julgue a afirmação sobre a narrativa$q$, $j${"stmt":"Enredo é a sequência de acontecimentos da história; normalmente tem apresentação, conflito, clímax e desfecho.","a":true}$j$, $q$Verdadeiro: o enredo (ou trama) é a cadeia de fatos, organizada em apresentação, complicação, clímax e desfecho.$q$, 1);
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:2', 4, 'bank', $q$Complete a frase sobre os elementos da narrativa$q$, $j${"parts":["O "," é o lugar onde a história acontece, e o "," é o momento em que ela se passa."],"a":["espaço","tempo"],"extra":["enredo","narrador"]}$j$, $q$Espaço é o onde; tempo é o quando. Enredo é o quê e narrador é quem conta.$q$, 1);
select public.fj_seed_q('lit', 'lit:generos', 'lit:generos:2', 5, 'order', $q$Ordene as partes típicas de um enredo, do começo ao fim$q$, $j${"items":["Apresentação das personagens e do espaço","Surgimento do conflito","Clímax, o momento de maior tensão","Desfecho"]}$j$, $q$Apresentação, conflito, clímax e desfecho: a estrutura clássica da narrativa.$q$, 1);

-- ---------------------------------------------------------------
-- lit:figuras:1 · Metáfora, metonímia e companhia
-- ---------------------------------------------------------------
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:1', 0, 'mc', $q$Em "O meu coração é um balde despejado" (Álvaro de Campos, heterônimo de Fernando Pessoa), há uma:$q$, $j${"opts":["Metonímia","Hipérbole","Metáfora","Eufemismo"],"a":2}$j$, $q$Metáfora: o coração é comparado a um balde vazio sem usar "como". É uma comparação implícita.$q$, 1);
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:1', 1, 'mc', $q$Na frase "Li todo o Machado de Assis", o nome do autor é usado no lugar da obra. Essa figura é a:$q$, $j${"opts":["Metáfora","Metonímia","Antítese","Personificação"],"a":1}$j$, $q$Metonímia: troca de uma palavra por outra com relação de proximidade (autor pela obra, parte pelo todo, marca pelo produto).$q$, 2);
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:1', 2, 'mc', $q$"Já disse um milhão de vezes que não vou!" apresenta um exagero intencional, chamado de:$q$, $j${"opts":["Hipérbole","Eufemismo","Ironia","Pleonasmo"],"a":0}$j$, $q$Hipérbole é o exagero proposital para dar ênfase.$q$, 1);
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:1', 3, 'tf', $q$Julgue a afirmação sobre as figuras de linguagem$q$, $j${"stmt":"Dizer que alguém \"partiu para um lugar melhor\" em vez de \"morreu\" é um exemplo de eufemismo, que suaviza uma ideia desagradável.","a":true}$j$, $q$Verdadeiro: eufemismo é a suavização de uma ideia dura ou desagradável.$q$, 1);
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:1', 4, 'bank', $q$Complete a frase sobre antítese e paradoxo$q$, $j${"parts":["Em \"Amor é fogo que arde sem se ver\" (Camões), a aproximação de ideias contrárias como \"ferida que dói e não se sente\" é a ","; quando a contradição está na mesma ideia, como \"dor que desatina sem doer\", chamamos de ","."],"a":["antítese","paradoxo"],"extra":["metáfora","hipérbole"]}$j$, $q$Antítese opõe ideias contrárias; paradoxo junta ideias que se contradizem na mesma afirmação.$q$, 3);
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:1', 5, 'match', $q$Associe a figura ao exemplo$q$, $j${"pairs":[["Personificação","O vento sussurrava segredos"],["Comparação","Forte como um touro"],["Ironia","Que lindo, chegou atrasado de novo!"],["Aliteração","O rato roeu a roupa do rei de Roma"]]}$j$, $q$Personificação dá ação humana a algo não humano; comparação usa "como"; ironia diz o contrário do que pensa; aliteração repete consoantes.$q$, 2);

-- lit:figuras:2 · Verso, rima e métrica
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:2', 0, 'mc', $q$Um soneto é um poema de:$q$, $j${"opts":["10 versos em uma estrofe","14 versos: dois quartetos e dois tercetos","12 versos em três quartetos","8 versos em duas estrofes"],"a":1}$j$, $q$O soneto tem 14 versos divididos em dois quartetos (4 versos) e dois tercetos (3 versos).$q$, 1);
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:2', 1, 'mc', $q$O verso de sete sílabas poéticas, muito usado em cantigas populares e na literatura de cordel, é chamado de:$q$, $j${"opts":["Decassílabo","Alexandrino","Redondilha maior","Redondilha menor"],"a":2}$j$, $q$Redondilha maior tem 7 sílabas; redondilha menor, 5; decassílabo, 10; alexandrino, 12.$q$, 2);
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:2', 2, 'mc', $q$A voz que fala no poema, que não se confunde com o autor, é chamada de:$q$, $j${"opts":["Narrador","Eu lírico","Personagem","Protagonista"],"a":1}$j$, $q$Eu lírico é a voz do poema; o narrador é a voz da narrativa. Nenhum dos dois é o autor de carne e osso.$q$, 1);
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:2', 3, 'tf', $q$Julgue a afirmação sobre os versos$q$, $j${"stmt":"Versos brancos são versos sem rima; versos livres são versos sem métrica fixa, como os preferidos pelos modernistas.","a":true}$j$, $q$Verdadeiro: branco = sem rima; livre = sem número fixo de sílabas.$q$, 2);
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:2', 4, 'bank', $q$Complete a frase sobre o poema$q$, $j${"parts":["Cada linha de um poema é um ","; o conjunto de versos agrupados é uma ","."],"a":["verso","estrofe"],"extra":["parágrafo","rima"]}$j$, $q$Verso é a linha; estrofe é o grupo de versos (como o parágrafo na prosa).$q$, 1);
select public.fj_seed_q('lit', 'lit:figuras', 'lit:figuras:2', 5, 'match', $q$Associe o tipo de verso ao número de sílabas poéticas$q$, $j${"pairs":[["Redondilha menor","5 sílabas"],["Redondilha maior","7 sílabas"],["Decassílabo","10 sílabas"],["Alexandrino","12 sílabas"]]}$j$, $q$As sílabas poéticas são contadas até a última tônica do verso.$q$, 2);

