select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:1', 0, 'mc', $q$O primeiro documento da literatura brasileira, que descreve a terra e os indígenas ao rei de Portugal em 1500, é:$q$, $j${"opts":["A Carta de Pero Vaz de Caminha","Os Lusíadas, de Camões","O Guarani, de José de Alencar","Prosopopeia, de Bento Teixeira"],"a":0}$j$, $q$A Carta de Caminha ao rei D. Manuel é o marco da literatura informativa do Quinhentismo.$q$, 1);
select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:1', 1, 'mc', $q$O poeta baiano do Barroco, conhecido como "Boca do Inferno" por suas sátiras à sociedade da época, é:$q$, $j${"opts":["Padre Antônio Vieira","Gregório de Matos","José de Anchieta","Cláudio Manuel da Costa"],"a":1}$j$, $q$Gregório de Matos escreveu poesia satírica, lírica e religiosa; a sátira à Bahia rendeu o apelido.$q$, 1);
select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:1', 2, 'mc', $q$O Sermão da Sexagésima e o Sermão de Santo Antônio aos Peixes, exemplos de conceptismo barroco, foram escritos por:$q$, $j${"opts":["Gregório de Matos","Bento Teixeira","Padre Antônio Vieira","Pero Vaz de Caminha"],"a":2}$j$, $q$Vieira é o grande nome da prosa barroca: sermões com raciocínio lógico e argumentação (conceptismo).$q$, 2);
select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:1', 3, 'tf', $q$Julgue a afirmação sobre o Barroco$q$, $j${"stmt":"O Barroco é marcado pelo conflito entre fé e razão, céu e terra, e usa muitas antíteses e paradoxos para expressar essa dualidade.","a":true}$j$, $q$Verdadeiro: o homem barroco vive dividido entre o prazer terreno e a salvação, e a linguagem reflete isso.$q$, 2);
select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:1', 4, 'bank', $q$Complete a frase sobre as duas vertentes do Barroco$q$, $j${"parts":["No Barroco, o "," valoriza o jogo de palavras e as imagens rebuscadas (Gregório de Matos); o "," valoriza o jogo de ideias e o raciocínio lógico (Vieira)."],"a":["cultismo","conceptismo"],"extra":["arcadismo","romantismo"]}$j$, $q$Cultismo: jogo de palavras (gongorismo). Conceptismo: jogo de conceitos (quevedismo).$q$, 3);
select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:1', 5, 'match', $q$Associe o autor à obra ou ao papel$q$, $j${"pairs":[["José de Anchieta","Autos e poemas jesuíticos para catequese"],["Pero Vaz de Caminha","Carta do achamento do Brasil"],["Gregório de Matos","Poesia satírica, lírica e religiosa"],["Bento Teixeira","Prosopopeia, marco inicial do Barroco no Brasil"]]}$j$, $q$Anchieta é a literatura jesuítica; Caminha, a informativa; Gregório, o poeta barroco; a Prosopopeia (1601) abre o Barroco.$q$, 2);

-- lit:origens:2 · Arcadismo
select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:2', 0, 'mc', $q$A publicação de "Obras", de Cláudio Manuel da Costa, em 1768, marca o início de qual movimento no Brasil?$q$, $j${"opts":["Barroco","Arcadismo","Romantismo","Realismo"],"a":1}$j$, $q$1768 é o marco do Arcadismo brasileiro, movimento ligado à Vila Rica dos inconfidentes.$q$, 1);
select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:2', 1, 'mc', $q$Em "Marília de Dirceu", Tomás Antônio Gonzaga adota o pseudônimo pastoril Dirceu. Esse hábito dos árcades reflete o ideal de:$q$, $j${"opts":["Vida simples no campo, longe da cidade (fugere urbem)","Exaltação da cidade e do progresso","Religiosidade barroca","Nacionalismo indianista"],"a":0}$j$, $q$Os árcades se fingiam de pastores para cantar a vida simples e a natureza, fugindo da cidade.$q$, 2);
select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:2', 2, 'mc', $q$Vários poetas árcades mineiros, como Gonzaga e Cláudio Manuel da Costa, participaram de qual movimento político?$q$, $j${"opts":["Revolta dos Malês","Inconfidência Mineira","Revolução Farroupilha","Conjuração Baiana"],"a":1}$j$, $q$Os poetas da Inconfidência Mineira (1789) foram presos; Gonzaga foi degredado para Moçambique.$q$, 2);
select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:2', 3, 'tf', $q$Julgue a afirmação sobre o Arcadismo$q$, $j${"stmt":"\"Carpe diem\" (aproveite o dia) e \"aurea mediocritas\" (a valorização da vida moderada) são ideias presentes na poesia árcade.","a":true}$j$, $q$Verdadeiro: os árcades retomam os clássicos latinos e seus ideais de equilíbrio e de aproveitar o presente.$q$, 2);
select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:2', 4, 'bank', $q$Complete a frase sobre a épica árcade$q$, $j${"parts":["\"O Uraguai\", de ","da Gama, e \"Caramuru\", de Santa Rita ",", são os poemas épicos do Arcadismo brasileiro."],"a":["Basílio","Durão"],"extra":["Gregório","Gonzaga"]}$j$, $q$Basílio da Gama (O Uraguai, 1769) e Santa Rita Durão (Caramuru, 1781) escreveram as epopeias árcades.$q$, 3);
select public.fj_seed_q('lit', 'lit:origens', 'lit:origens:2', 5, 'match', $q$Associe a expressão latina ao seu sentido no Arcadismo$q$, $j${"pairs":[["Fugere urbem","Fugir da cidade"],["Locus amoenus","Lugar agradável, a natureza idealizada"],["Carpe diem","Aproveitar o momento"],["Aurea mediocritas","Valorizar a vida simples e equilibrada"]]}$j$, $q$Os quatro lemas resumem o programa árcade: campo, natureza, presente e moderação.$q$, 2);

