select public.fj_seed_q('lit', 'lit:contemp', 'lit:contemp:1', 0, 'mc', $q$"Grande Sertão: Veredas" (1956) é narrado por Riobaldo, jagunço que conta sua vida e seu amor por Diadorim. O autor é:$q$, $j${"opts":["Graciliano Ramos","João Guimarães Rosa","Jorge Amado","Ariano Suassuna"],"a":1}$j$, $q$Guimarães Rosa, médico e diplomata mineiro, reinventou a fala do sertão: "o sertão é do tamanho do mundo".$q$, 1);
select public.fj_seed_q('lit', 'lit:contemp', 'lit:contemp:1', 1, 'mc', $q$Uma marca do estilo de Guimarães Rosa é:$q$, $j${"opts":["A linguagem jornalística objetiva","A invenção de palavras (neologismos) e a recriação da fala sertaneja","O verso parnasiano","O narrador defunto"],"a":1}$j$, $q$Rosa cria palavras, mistura arcaísmos e regionalismos e dá ao sertão uma dimensão universal.$q$, 2);
select public.fj_seed_q('lit', 'lit:contemp', 'lit:contemp:1', 2, 'mc', $q$"A Hora da Estrela", de Clarice Lispector, conta a história de Macabéa, uma nordestina pobre no Rio. A obra se destaca por:$q$, $j${"opts":["Ser um poema épico","Misturar a história de Macabéa com as reflexões do narrador Rodrigo S. M. sobre o ato de escrever","Narrar a Guerra de Canudos","Idealizar a vida no campo"],"a":1}$j$, $q$O narrador Rodrigo S. M. interrompe a história para pensar na escrita: é metalinguagem. O livro foi o último de Clarice (1977).$q$, 2);
select public.fj_seed_q('lit', 'lit:contemp', 'lit:contemp:1', 3, 'tf', $q$Julgue a afirmação sobre João Cabral$q$, $j${"stmt":"\"Morte e Vida Severina\", de João Cabral de Melo Neto, é um auto de Natal pernambucano que acompanha o retirante Severino em sua viagem do sertão ao Recife.","a":true}$j$, $q$Verdadeiro: Severino segue o rio Capibaribe e encontra a morte por todo o caminho, até o nascimento de uma criança no mangue.$q$, 2);
select public.fj_seed_q('lit', 'lit:contemp', 'lit:contemp:1', 4, 'bank', $q$Complete a frase sobre Clarice Lispector$q$, $j${"parts":["Clarice estreou com \"Perto do Coração ","\" (1943); sua prosa explora o fluxo de consciência e a ",", momento de revelação súbita no cotidiano, como no conto \"Amor\"."],"a":["Selvagem","epifania"],"extra":["Sertão","sátira"]}$j$, $q$Perto do Coração Selvagem (1943) é a estreia; a epifania é o instante de revelação, marca dos contos de Laços de Família.$q$, 3);
