select public.fj_seed_q('lit', 'lit:contemp', 'lit:contemp:2', 0, 'mc', $q$O Concretismo (anos 1950), de Augusto de Campos, Haroldo de Campos e Décio Pignatari, propõe:$q$, $j${"opts":["Poemas longos e narrativos","Poemas visuais que exploram a disposição das palavras na página","O retorno ao soneto","A poesia religiosa"],"a":1}$j$, $q$O poema concreto é verbivocovisual: palavra, som e imagem na página, sem verso tradicional.$q$, 2);
